{"PLAYER_TIRED_HUNGRY","reg=civilian,family|tmp=seasoned|st=friendly|hour=16,5",{"You look plumb give out, there's a spare cot in the back room if you want it for tonight"},false,{[1]="STAY_NIGHT"}},
