{"PLAYER_TIRED_HUNGRY","reg=civilian,family,worker,rescue|st=hostile",{"Starve, then, you're not getting mine"}},
{"PLAYER_TIRED_HUNGRY","reg=worker|st=friendly,neutral",{"Plant cafeteria had a freezer full of corn dogs, power's out, so now they're just corn dogs - want one?"},false,{[1]="SHARE_FOOD"}},
