{"PLAYER_TIRED_HUNGRY","reg=rescue|role=rescue_clergy|st=friendly,neutral|world=building",{"Church pantry's down to canned yams and communion juice, you're welcome to both - nobody's counting"}},
{"PLAYER_TIRED_HUNGRY","reg=law,swat|st=friendly,neutral|world=vehicle",{"Sit on the bumper, I've got a granola bar and a thermos of coffee that's mostly cold - take both"}},
